import Ajv2020 from "ajv/dist/2020";
import { writePdfDictionary,readPdfDictionary } from "../../../🪶️sqlite/🧩️cos/🟦️.ts";
import type { PdfDictEntry } from "../../../🟦️.ts";

test("PDF UA initial neutral preserves literal raw references and typed marks",async()=>{
  const fixture=JSON.parse(await Bun.file(new URL("../../../🪶️sqlite/🧫️fixtures/♿️ua-initial/🔣️.json",import.meta.url)).text()),schema=JSON.parse(await Bun.file(new URL("../../../🪶️sqlite/🧫️fixtures/♿️ua-initial/🧬️schema/🔣️.json",import.meta.url)).text()),validate=new Ajv2020({strict:true}).compile(schema);
  expect(validate(fixture)).toBe(true);for(const bad of [{...fixture,documentLanguage:"en"},{...fixture,pages:{...fixture.pages,num:6}},{...fixture,unexpected:true}])expect(validate(bad)).toBe(false);
  const ref=(num:number)=>({kind:"ref" as const,num,gen:0}),name=(value:string)=>({kind:"name" as const,value});
  const dictionaries:PdfDictEntry[][]=[
    [{key:"Type",value:name("Catalog")},{key:"Pages",value:ref(5)},{key:"MarkInfo",value:ref(2)},{key:"StructTreeRoot",value:ref(3)},{key:"Lang",value:{kind:"str",value:[117,110,100]}},{key:"ViewerPreferences",value:ref(4)}],
    [{key:"Marked",value:{kind:"bool",value:true}}],
    [{key:"Type",value:name("StructTreeRoot")}],
    [{key:"DisplayDocTitle",value:{kind:"bool",value:true}}],
    [{key:"Type",value:name("Pages")},{key:"Kids",value:{kind:"array",value:[]}},{key:"Count",value:{kind:"int",value:0n}}],
    [{key:"Root",value:ref(1)}],
  ];
  const mark={marked:true,userProperties:false,suspects:false},preferences={hideToolbar:false,hideMenubar:false,hideWindowUi:false,fitWindow:false,centerWindow:false,displayDocTitle:true,nonFullScreenPageMode:null,direction:null,viewArea:null,viewClip:null,printArea:null,printClip:null,printScaling:null,duplex:null,pickTrayByPdfSize:false,printPageRange:[],numCopies:null,extra:[]};
  const out=await PdfProjection.create(PDF17_SQLITE_SCHEMA,{},pdfAnnotationNumberColumns),keys:bigint[]=[];for(const dictionary of dictionaries)keys.push(await writePdfDictionary(out,dictionary));const markKey=await writePdfMarkInfo(out,mark),preferencesKey=await writePdfPreferences(out,preferences),bytes=await exportSqliteDatabase(await out.finish()),sql=Database.deserialize(bytes);
  expect(sql.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(sql.query("PRAGMA foreign_key_check").all()).toEqual([]);
  expect(sql.query("SELECT e.key,v.reference_number AS number,v.reference_generation AS generation FROM pdf_cos_dictionary_entry e JOIN pdf_cos_value v ON v.id=e.value_id WHERE v.kind='reference' ORDER BY e.key").all()).toEqual([{key:"MarkInfo",number:2,generation:0},{key:"Pages",number:5,generation:0},{key:"Root",number:1,generation:0},{key:"StructTreeRoot",number:3,generation:0},{key:"ViewerPreferences",number:4,generation:0}]);
  expect(sql.query("SELECT e.key,hex(v.byte_string) AS bytes FROM pdf_cos_dictionary_entry e JOIN pdf_cos_value v ON v.id=e.value_id WHERE e.key='Lang'").get()).toEqual({key:"Lang",bytes:"756E64"});
  expect(sql.query("SELECT marked,user_properties AS userProperties,suspects FROM pdf_mark_info").get()).toEqual({marked:1,userProperties:0,suspects:0});expect(sql.query("SELECT display_doc_title AS displayDocTitle FROM pdf_viewer_preferences").get()).toEqual({displayDocTitle:1});
  const reader=await PdfReader.create(await importSqliteDatabase(bytes),PDF17_SQLITE_SCHEMA,{},pdfAnnotationNumberColumns);for(const[index,key]of keys.entries())expect(await readPdfDictionary(reader,key)).toEqual(dictionaries[index]);expect(await readPdfMarkInfo(reader,markKey)).toEqual(mark);expect(await readPdfPreferences(reader,preferencesKey)).toEqual(preferences);await reader.finish();sql.close();
},{timeout:30_000});
